void Solver::bump_var(int var, double coeff) {
    // Compute the increment and tentative new activity
    double inc = var_inc * coeff;
    double new_act = activity[var] + inc;

    // If the new activity would overflow, rescale all activities and var_inc
    if (new_act > 1e100) {
        const double scale = 1e-100;
        for (int i = 1; i <= vars; ++i) activity[i] *= scale;
        var_inc *= scale;
        // Apply scaling to the current variable's activity as well
        activity[var] = new_act * scale;
    } else {
        activity[var] = new_act;
    }

    // Update VSIDS heap if the variable is present
    if (vsids.inHeap(var)) vsids.update(var);
}
